package org.apache.commons.math.stat.correlation;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.distribution.TDistribution;
import org.apache.commons.math.distribution.TDistributionImpl;
import org.apache.commons.math.linear.BlockRealMatrix;
import org.apache.commons.math.linear.RealMatrix;
import org.apache.commons.math.stat.regression.SimpleRegression;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.linear.RealMatrix;
import org.apache.commons.math3.stat.correlation.PearsonsCorrelation;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for PearsonsCorrelation.getCorrelationPValues().
 */
public class PearsonsCorrelation_getCorrelationPValues_TriageGen2Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testGetCorrelationPValuesWithPerfectCorrelation() {
        // Data with perfect correlation (r = 1.0)
        double[][] data = {
            {1.0, 2.0, 3.0},
            {2.0, 4.0, 6.0},
            {3.0, 6.0, 9.0}
        };
        PearsonsCorrelation correlation = new PearsonsCorrelation(data);
        RealMatrix pValues = correlation.getCorrelationPValues();

        int nVars = 3;
        Assert.assertEquals(nVars, pValues.getRowDimension());
        Assert.assertEquals(nVars, pValues.getColumnDimension());

        // Diagonal should be 0.0
        for (int i = 0; i < nVars; i++) {
            Assert.assertEquals(0.0, pValues.getEntry(i, i), EPSILON);
        }

        // Off-diagonal for perfect correlation should be 0.0 (or very close to it)
        // Because r=1, t becomes Infinity, cumulativeProbability(inf) = 1, 2*(1-1) = 0
        Assert.assertEquals(0.0, pValues.getEntry(0, 1), EPSILON);
        Assert.assertEquals(0.0, pValues.getEntry(1, 0), EPSILON);
    }

    @Test
    public void testGetCorrelationPValuesWithKnownValues() {
        // Small dataset to calculate manually
        // x = [1, 2, 3], y = [1, 5, 7]
        // mean x = 2, mean y = 4.333...
        // r approx 0.9607689
        // n = 3, df = 1
        double[][] data = {
            {1.0, 2.0, 3.0},
            {1.0, 5.0, 7.0}
        };
        PearsonsCorrelation correlation = new PearsonsCorrelation(data);
        RealMatrix pValues = correlation.getCorrelationPValues();

        // Check symmetry and diagonal
        Assert.assertEquals(0.0, pValues.getEntry(0, 0), EPSILON);
        Assert.assertEquals(0.0, pValues.getEntry(1, 1), EPSILON);
        Assert.assertEquals(pValues.getEntry(0, 1), pValues.getEntry(1, 0), EPSILON);

        // p-value should be between 0 and 1
        double pVal = pValues.getEntry(0, 1);
        Assert.assertTrue(pVal > 0.0 && pVal < 1.0);
    }

    @Test
    public void testGetCorrelationPValuesWithNoCorrelation() {
        // Data with zero correlation
        double[][] data = {
            {1.0, 2.0, 3.0},
            {1.0, 0.0, 1.0},
            {5.0, 2.0, 1.0}
        };
        PearsonsCorrelation correlation = new PearsonsCorrelation(data);
        RealMatrix pValues = correlation.getCorrelationPValues();

        // Check that p-values are calculated and non-zero for non-identity diagonal
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (i != j) {
                    Assert.assertTrue(pValues.getEntry(i, j) >= 0.0);
                }
            }
        }
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testGetCorrelationPValuesWithInsufficientObservations() {
        // nObs - 2 must be > 0 for TDistribution. 
        // If nObs = 2, TDistribution(0) might throw exception.
        double[][] data = {
            {1.0, 2.0},
            {3.0, 4.0}
        };
        PearsonsCorrelation correlation = new PearsonsCorrelation(data);
        // This should trigger a MathIllegalArgumentException or similar due to df <= 0
        correlation.getCorrelationPValues();
    }

    @Test
    public void testGetCorrelationPValuesWithConstantData() {
        // Constant data leads to undefined correlation (division by zero in r calculation)
        // However, PearsonsCorrelation constructor handles this. 
        // If r is NaN, the math inside getCorrelationPValues will produce NaN.
        double[][] data = {
            {1.0, 1.0, 1.0},
            {2.0, 3.0, 4.0}
        };
        PearsonsCorrelation correlation = new PearsonsCorrelation(data);
        RealMatrix pValues = correlation.getCorrelationPValues();

        // If r is NaN, p-value will be NaN
        Assert.assertTrue(Double.isNaN(pValues.getEntry(0, 1)));
    }
}
